// Prelude and standard-module table: signature, Python lowering, docs.
pub struct Builtin {
    pub name: &'static str,
    pub sig: &'static str,
    /// Python expression when used as a value
    pub value: &'static str,
    /// how a full application lowers: `` (call the value), `func:NAME`, `not`, `in`, `method:NAME`
    pub app: &'static str,
    pub doc: &'static str,
}

